import java.util.List;

public class Statistik {

    record Buch(String titel, int seiten) { }

    public static void main(String[] args) {
        List<Buch> buecher = List.of(
                new Buch("Java", 500),
                new Buch("Kurzgeschichten", 120),
                new Buch("OOP", 300));

        buecher.stream()
               .filter(b -> b.seiten() > 200)
               .sorted((a, b) -> a.titel().compareTo(b.titel()))
               .forEach(b -> System.out.println("- " + b.titel()));

        int gesamt = buecher.stream().mapToInt(b -> b.seiten()).sum();
        System.out.println("Gesamtseiten: " + gesamt);
    }
}
